#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_TOKEN_LEN 4096
#define HMAC_LEN 32

static const char b64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

typedef struct {
    char *data;
    size_t len;
    size_t cap;
} Buffer;

static int buffer_init(Buffer *buf, size_t initial_cap) {
    buf->data = (char *)malloc(initial_cap);
    if (!buf->data) return -1;
    buf->len = 0;
    buf->cap = initial_cap;
    return 0;
}

static void buffer_free(Buffer *buf) {
    if (buf->data) {
        memset(buf->data, 0, buf->cap);
        free(buf->data);
        buf->data = NULL;
    }
    buf->len = 0;
    buf->cap = 0;
}

/* Compute required output size for base64 encoding.
 * Standard formula: 4 * ceil(n/3) + 1 for null terminator.
 * We add 1 for safety margin on boundary cases. */
static size_t b64_encoded_size(size_t input_len) {
    if (input_len == 0) return 0;
    /* Ceiling division: (n + 2) / 3 * 4 */
    size_t output_len = ((input_len + 2) / 3) * 4;
    return output_len; /* caller adds +1 for null terminator */
}

/* Base64 encode src into dst. dst must have at least
 * b64_encoded_size(src_len) + 1 bytes available. */
static int b64_encode(const uint8_t *src, size_t src_len, char *dst, size_t dst_cap) {
    size_t needed = b64_encoded_size(src_len) + 1;
    if (dst_cap < needed) return -1;

    size_t i = 0, j = 0;
    for (; i + 2 < src_len; i += 3) {
        uint32_t triple = ((uint32_t)src[i] << 16) |
                         ((uint32_t)src[i+1] << 8) |
                         ((uint32_t)src[i+2]);
        dst[j++] = b64_table[(triple >> 18) & 0x3F];
        dst[j++] = b64_table[(triple >> 12) & 0x3F];
        dst[j++] = b64_table[(triple >> 6) & 0x3F];
        dst[j++] = b64_table[triple & 0x3F];
    }

    if (i < src_len) {
        uint32_t triple = (uint32_t)src[i] << 16;
        if (i + 1 < src_len) triple |= (uint32_t)src[i+1] << 8;

        dst[j++] = b64_table[(triple >> 18) & 0x3F];
        dst[j++] = b64_table[(triple >> 12) & 0x3F];
        dst[j++] = (i + 1 < src_len) ? b64_table[(triple >> 6) & 0x3F] : '=';
        dst[j++] = '=';
    }
    dst[j] = '\0';
    return 0;
}

/* Base64 decode: compute output size from encoded input */
static size_t b64_decoded_size(const char *src, size_t src_len) {
    if (src_len == 0) return 0;
    if (src_len % 4 != 0) return 0; /* invalid */
    /* Each 4 chars -> 3 bytes, minus padding */
    size_t len = (src_len / 4) * 3;
    if (src_len >= 1 && src[src_len - 1] == '=') len--;
    if (src_len >= 2 && src[src_len - 2] == '=') len--;
    return len;
}

static int b64_char_value(char c) {
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+') return 62;
    if (c == '/') return 63;
    return -1;
}

static int b64_decode(const char *src, size_t src_len, uint8_t *dst, size_t dst_cap) {
    if (src_len % 4 != 0) return -1;
    size_t out_len = b64_decoded_size(src, src_len);
    if (out_len == 0 && src_len > 0) return -1;
    if (dst_cap < out_len) return -1;

    size_t j = 0;
    for (size_t i = 0; i < src_len; i += 4) {
        int a = b64_char_value(src[i]);
        int b = b64_char_value(src[i+1]);
        int c = (src[i+2] == '=') ? 0 : b64_char_value(src[i+2]);
        int d = (src[i+3] == '=') ? 0 : b64_char_value(src[i+3]);
        if (a < 0 || b < 0 || c < 0 || d < 0) return -1;

        uint32_t triple = ((uint32_t)a << 18) | ((uint32_t)b << 12) |
                         ((uint32_t)c << 6) | (uint32_t)d;
        if (j < out_len) dst[j++] = (triple >> 16) & 0xFF;
        if (j < out_len) dst[j++] = (triple >> 8) & 0xFF;
        if (j < out_len) dst[j++] = triple & 0xFF;
    }
    return (int)out_len;
}

/* Token structure: base64(payload) + "." + base64(signature)
 * Payload: JSON-like "user=<username>&exp=<timestamp>&role=<role>" */

typedef struct {
    char user[256];
    uint64_t expiry;
    char role[64];
} TokenPayload;

/* Parse a token payload from decoded bytes */
static int parse_payload(const uint8_t *data, size_t len, TokenPayload *out) {
    memset(out, 0, sizeof(*out));

    if (len == 0 || len > 1024) return -1;

    /* Safety: ensure null-terminated for string ops */
    char *buf = (char *)malloc(len + 1);
    if (!buf) return -1;
    memcpy(buf, data, len);
    buf[len] = '\0';

    char *user_start = strstr(buf, "user=");
    char *exp_start = strstr(buf, "&exp=");
    char *role_start = strstr(buf, "&role=");

    if (!user_start || !exp_start || !role_start) {
        free(buf);
        return -1;
    }

    /* Validate ordering: user must come before exp, exp before role */
    if (user_start >= exp_start || exp_start >= role_start) {
        free(buf);
        return -1;
    }

    user_start += 5;
    size_t user_len = (size_t)(exp_start - user_start);
    if (user_len >= sizeof(out->user)) user_len = sizeof(out->user) - 1;
    memcpy(out->user, user_start, user_len);

    exp_start += 5;
    out->expiry = strtoull(exp_start, NULL, 10);

    role_start += 6;
    char *role_end = strchr(role_start, '&');
    size_t role_len = role_end ? (size_t)(role_end - role_start) : strlen(role_start);
    if (role_len >= sizeof(out->role)) role_len = sizeof(out->role) - 1;
    memcpy(out->role, role_start, role_len);

    free(buf);
    return 0;
}

/* Simple HMAC-like signing (simplified for demonstration).
 * In production this would use a proper HMAC-SHA256. */
static void compute_mac(const uint8_t *key, size_t key_len,
                       const uint8_t *msg, size_t msg_len,
                       uint8_t *out_mac) {
    /* Simplified: XOR key with message bytes, then hash-like mixing */
    uint8_t state[HMAC_LEN];
    memset(state, 0x36, HMAC_LEN);

    for (size_t i = 0; i < key_len; i++) {
        state[i % HMAC_LEN] ^= key[i];
    }
    for (size_t i = 0; i < msg_len; i++) {
        state[i % HMAC_LEN] ^= msg[i];
        /* Mix */
        state[(i + 1) % HMAC_LEN] += state[i % HMAC_LEN];
    }
    memcpy(out_mac, state, HMAC_LEN);
}

/* Verify token: decode, check MAC, parse payload.
 * Returns 0 on success, fills out payload. */
static int verify_token(const char *token, size_t token_len,
                       const uint8_t *key, size_t key_len,
                       TokenPayload *payload) {
    if (token_len > MAX_TOKEN_LEN || token_len == 0) return -1;

    /* Find the dot separator */
    const char *dot = memchr(token, '.', token_len);
    if (!dot) return -1;

    size_t payload_b64_len = (size_t)(dot - token);
    size_t sig_b64_len = token_len - payload_b64_len - 1;

    if (payload_b64_len == 0 || sig_b64_len == 0) return -1;
    if (payload_b64_len % 4 != 0 || sig_b64_len % 4 != 0) return -1;

    /* Decode payload */
    size_t payload_dec_size = b64_decoded_size(token, payload_b64_len);
    if (payload_dec_size == 0) return -1;
    uint8_t *payload_dec = (uint8_t *)malloc(payload_dec_size + 1);
    if (!payload_dec) return -1;

    int dec_len = b64_decode(token, payload_b64_len, payload_dec, payload_dec_size);
    if (dec_len < 0) {
        free(payload_dec);
        return -1;
    }

    /* Decode signature */
    const char *sig_b64 = dot + 1;
    size_t sig_dec_size = b64_decoded_size(sig_b64, sig_b64_len);
    if (sig_dec_size != HMAC_LEN) {
        free(payload_dec);
        return -1;
    }
    uint8_t *sig_dec = (uint8_t *)malloc(sig_dec_size);
    if (!sig_dec) {
        free(payload_dec);
        return -1;
    }

    int sig_len = b64_decode(sig_b64, sig_b64_len, sig_dec, sig_dec_size);
    if (sig_len < 0 || (size_t)sig_len != HMAC_LEN) {
        free(payload_dec);
        free(sig_dec);
        return -1;
    }

    /* Verify MAC over the base64-encoded payload (not decoded) */
    uint8_t expected_mac[HMAC_LEN];
    compute_mac(key, key_len, (const uint8_t *)token, payload_b64_len, expected_mac);

    /* Constant-time comparison */
    volatile uint8_t diff = 0;
    for (int i = 0; i < HMAC_LEN; i++) {
        diff |= sig_dec[i] ^ expected_mac[i];
    }

    free(sig_dec);

    if (diff != 0) {
        free(payload_dec);
        return -1;
    }

    /* Parse the verified payload */
    int ret = parse_payload(payload_dec, (size_t)dec_len, payload);
    free(payload_dec);
    return ret;
}

/* Generate a signed token for a user */
static int generate_token(const char *user, uint64_t expiry, const char *role,
                         const uint8_t *key, size_t key_len,
                         char *out_token, size_t out_cap) {
    if (!user || !role || !key || key_len == 0) return -1;
    if (strlen(user) > 200 || strlen(role) > 50) return -1;

    /* Build payload string */
    char payload_str[1024];
    int plen = snprintf(payload_str, sizeof(payload_str),
                       "user=%s&exp=%llu&role=%s", user,
                       (unsigned long long)expiry, role);
    if (plen < 0 || (size_t)plen >= sizeof(payload_str)) return -1;

    /* Base64 encode payload */
    size_t payload_b64_size = b64_encoded_size((size_t)plen) + 1;
    char *payload_b64 = (char *)malloc(payload_b64_size);
    if (!payload_b64) return -1;

    if (b64_encode((const uint8_t *)payload_str, (size_t)plen,
                   payload_b64, payload_b64_size) != 0) {
        free(payload_b64);
        return -1;
    }

    size_t payload_b64_len = strlen(payload_b64);

    /* Compute MAC over base64-encoded payload */
    uint8_t mac[HMAC_LEN];
    compute_mac(key, key_len, (const uint8_t *)payload_b64, payload_b64_len, mac);

    /* Base64 encode MAC */
    size_t mac_b64_size = b64_encoded_size(HMAC_LEN) + 1;
    char *mac_b64 = (char *)malloc(mac_b64_size);
    if (!mac_b64) {
        free(payload_b64);
        return -1;
    }

    if (b64_encode(mac, HMAC_LEN, mac_b64, mac_b64_size) != 0) {
        free(payload_b64);
        free(mac_b64);
        return -1;
    }

    size_t mac_b64_len = strlen(mac_b64);

    /* Assemble: payload_b64 + "." + mac_b64 */
    size_t total = payload_b64_len + 1 + mac_b64_len + 1;
    if (total > out_cap) {
        free(payload_b64);
        free(mac_b64);
        return -1;
    }

    memcpy(out_token, payload_b64, payload_b64_len);
    out_token[payload_b64_len] = '.';
    memcpy(out_token + payload_b64_len + 1, mac_b64, mac_b64_len);
    out_token[payload_b64_len + 1 + mac_b64_len] = '\0';

    free(payload_b64);
    free(mac_b64);
    return 0;
}

/* Access control check */
static int check_admin_access(const TokenPayload *payload) {
    /* Role must be exactly "admin" */
    if (strcmp(payload->role, "admin") != 0) return -1;
    return 0;
}

/* Process an admin action request.
 * token_str: the authentication token
 * action: the requested action
 * key/key_len: HMAC key */
int process_admin_request(const char *token_str, const char *action,
                         const uint8_t *key, size_t key_len) {
    if (!token_str || !action || !key || key_len == 0) return -1;

    size_t token_len = strlen(token_str);
    TokenPayload payload;

    if (verify_token(token_str, token_len, key, key_len, &payload) != 0) {
        fprintf(stderr, "Token verification failed\n");
        return -1;
    }

    if (check_admin_access(&payload) != 0) {
        fprintf(stderr, "Access denied for user: %s (role: %s)\n",
                payload.user, payload.role);
        return -1;
    }

    printf("Admin action '%s' authorized for user '%s'\n", action, payload.user);
    return 0;
}

int main(int argc, char **argv) {
    /* Demo: generate and verify a token */
    const uint8_t key[] = "supersecretkey12345678901234567890";
    size_t key_len = 32;

    char token[MAX_TOKEN_LEN];

    if (argc < 3) {
        fprintf(stderr, "Usage: %s <username> <role>\n", argv[0]);
        return 1;
    }

    if (generate_token(argv[1], 9999999999ULL, argv[2],
                      key, key_len, token, sizeof(token)) != 0) {
        fprintf(stderr, "Token generation failed\n");
        return 1;
    }

    printf("Generated token: %s\n", token);

    /* Now verify and process */
    return process_admin_request(token, "delete_all_users", key, key_len);
}
